import android.widget.Toast

fun analyzeNetworkScan(target: String, openPorts: List<Long>, timestamp: Long, scanMethod: String?) {
    val message = """
        |THINK DEEPLY:
        |Analyze this network scan result for anomalies:

        |{"target": "$target", "openPorts": [135, 445], "timestamp": $timestamp, "scanMethod": "$scanMethod"}
    """.trimIndent()

    if (scanMethod?.startsWith("native-net")) {
        // Check if the method uses native libraries
        Toast.makeText(this@analyzeNetworkScan, message, Toast.LENGTH_SHORT).show()
    } else {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
    }
}

// Call the function with specific values
analyzeNetworkScan("127.0.0.1", listOf(135L, 445L), System.currentTimeMillis(), "native-net")
